'use client'

import {
  cn,
  DismissableLayer,
  focusElement,
  Presence,
  useControllableSignal,
  useRovingFocus,
  useSignalEffect,
  useSignals,
} from '@cascivo/core'
import { useId, useRef } from 'react'
import type { ReactNode } from 'react'
import styles from './fab.module.css'

export interface FabAction {
  /** Stable React key. Provide when `label` may repeat across actions. */
  id?: string
  /** Accessible name and visible label for the speed-dial item. */
  label: string
  icon: ReactNode
  onSelect: () => void
  disabled?: boolean
}

interface FabBaseProps {
  /** The main button icon. */
  children: ReactNode
  /** Called on press when there is no speed-dial. Ignored when `actions` is set. */
  onClick?: () => void
  /** Speed-dial actions revealed above the button when opened. */
  actions?: FabAction[]
  /**
   * Screen corner the button is pinned to: `bottom-end` or `bottom-start`. Safe-area insets
   * are honoured either way.
   *
   * @defaultValue `bottom-end`
   * @see the component manifest
   */
  position?: 'bottom-end' | 'bottom-start'
  /** Controlled speed-dial open state. */
  open?: boolean
  /** Initial speed-dial open state for uncontrolled use. */
  defaultOpen?: boolean
  /** Called whenever the speed-dial open state should change. */
  onOpenChange?: (open: boolean) => void
  className?: string
}

/**
 * Exactly one of `label` / `ariaLabel` is required — the main button is icon-only, so a
 * missing accessible name is a bug and stays enforced by the type rather than a dev warning.
 * `ariaLabel` is the catalog's name for a string nothing paints; `Fab` predates the
 * convention and shipped `label`, so both work and neither is deprecated. Same shape as
 * `IconButton`.
 */
export type FabProps = FabBaseProps &
  ({ label: string; ariaLabel?: never } | { ariaLabel: string; label?: never })

/**
 * Floating action button anchored to a screen corner. On its own it is a single
 * fixed button; given `actions` it becomes a speed-dial whose main button toggles a
 * role="menu" of secondary actions (vertical roving focus, Escape / outside press to
 * collapse, focus returns to the button). Fixed position honours the safe-area insets;
 * CSS-only motion, no animation library.
 */
export function Fab({
  children,
  ariaLabel,
  label,
  onClick,
  actions,
  position = 'bottom-end',
  open,
  defaultOpen,
  onOpenChange,
  className,
}: FabProps) {
  useSignals()
  const hasDial = actions != null && actions.length > 0
  const [isOpen, setOpen] = useControllableSignal<boolean>({
    value: open,
    defaultValue: defaultOpen ?? false,
    onChange: onOpenChange,
  })

  const roving = useRovingFocus({ orientation: 'vertical', loop: true })
  const fabRef = useRef<HTMLButtonElement>(null)
  const dialRef = useRef<HTMLElement>(null)
  const menuId = useId()

  // Move focus into the dial on open and back to the button on close.
  const wasOpenRef = useRef(false)
  useSignalEffect(() => {
    const next = hasDial && isOpen.value
    if (next && !wasOpenRef.current) {
      dialRef.current
        ?.querySelector<HTMLElement>('[role="menuitem"]:not([aria-disabled="true"])')
        ?.focus()
    } else if (!next && wasOpenRef.current) {
      focusElement(fabRef.current)
    }
    wasOpenRef.current = next
  })

  const selectAction = (action: FabAction): void => {
    if (action.disabled) return
    action.onSelect()
    setOpen(false)
  }

  const mainButton = (
    <button
      ref={fabRef}
      type="button"
      aria-label={label ?? ariaLabel}
      className={styles['fab']}
      {...(hasDial
        ? {
            'aria-haspopup': 'menu' as const,
            'aria-expanded': isOpen.value,
            'aria-controls': menuId,
            'data-state': isOpen.value ? 'open' : 'closed',
            onClick: () => setOpen(!isOpen.value),
          }
        : { onClick })}
    >
      <span className={styles['icon']} aria-hidden="true">
        {children}
      </span>
    </button>
  )

  if (!hasDial) {
    return (
      <div className={cn(styles['root'], className)} data-position={position}>
        {mainButton}
      </div>
    )
  }

  return (
    <DismissableLayer
      onDismiss={() => setOpen(false)}
      escapeDismisses={isOpen.value}
      disableOutsidePointer={!isOpen.value}
    >
      <div className={cn(styles['root'], className)} data-position={position}>
        <Presence present={isOpen}>
          <menu
            ref={dialRef as React.Ref<HTMLMenuElement>}
            id={menuId}
            role="menu"
            aria-label={label ?? ariaLabel}
            className={styles['dial']}
          >
            {actions.map((action, index) => {
              const itemProps = roving.getItemProps(index)
              return (
                <li key={action.id ?? index} role="presentation" className={styles['dialItem']}>
                  <button
                    ref={itemProps.ref as React.Ref<HTMLButtonElement>}
                    type="button"
                    role="menuitem"
                    tabIndex={itemProps.tabIndex}
                    aria-disabled={action.disabled || undefined}
                    className={styles['action']}
                    onKeyDown={itemProps.onKeyDown}
                    onFocus={itemProps.onFocus}
                    onClick={() => selectAction(action)}
                  >
                    <span className={styles['actionLabel']}>{action.label}</span>
                    <span className={styles['actionIcon']} aria-hidden="true">
                      {action.icon}
                    </span>
                  </button>
                </li>
              )
            })}
          </menu>
        </Presence>
        {mainButton}
      </div>
    </DismissableLayer>
  )
}

@layer cascivo.component {
  .root {
    position: fixed;
    z-index: var(--cascivo-z-dropdown, 30);
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-3);
    inset-block-end: calc(var(--cascivo-space-6) + env(safe-area-inset-bottom, 0px));

    &[data-position='bottom-end'] {
      inset-inline-end: calc(var(--cascivo-space-6) + env(safe-area-inset-right, 0px));
      align-items: flex-end;
    }

    &[data-position='bottom-start'] {
      inset-inline-start: calc(var(--cascivo-space-6) + env(safe-area-inset-left, 0px));
      align-items: flex-start;
    }
  }

  .fab {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 3.5rem;
    block-size: 3.5rem;
    padding: 0;
    color: var(--cascivo-color-accent-content);
    background: var(--cascivo-color-accent);
    border: none;
    border-radius: var(--cascivo-radius-full, 9999px);
    box-shadow: var(--cascivo-shadow-overlay);
    cursor: pointer;
    transition:
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover {
      background: var(--cascivo-color-accent-hover, var(--cascivo-color-accent));
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }
  }

  .icon {
    display: inline-flex;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    /* Rotate the icon (e.g. + → ×) while the speed-dial is open. */
    transition: rotate var(--cascivo-motion-emphasis, 200ms var(--cascivo-ease-out));

    .fab[data-state='open'] & {
      rotate: 45deg;
    }
  }

  .dial {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-2);
    margin: 0;
    padding: 0;
    list-style: none;
    align-items: inherit;

    opacity: 1;
    translate: 0 0;
    transition:
      opacity var(--cascivo-motion-enter),
      translate var(--cascivo-motion-enter);

    &[data-state='closed'] {
      opacity: 0;
      translate: 0 var(--cascivo-space-3);
      transition:
        opacity var(--cascivo-motion-exit),
        translate var(--cascivo-motion-exit);
    }

    @starting-style {
      &[data-state='open'] {
        opacity: 0;
        translate: 0 var(--cascivo-space-3);
      }
    }
  }

  .dialItem {
    display: flex;
  }

  .action {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-3);
    min-block-size: var(--cascivo-target-min-coarse, 2.75rem);
    padding-block: var(--cascivo-space-2);
    padding-inline: var(--cascivo-space-4);
    color: var(--cascivo-color-text);
    background: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-full, 9999px);
    box-shadow: var(--cascivo-shadow-overlay);
    cursor: pointer;
    transition: background-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    .root[data-position='bottom-start'] & {
      flex-direction: row-reverse;
    }

    &:hover {
      background: var(--cascivo-color-bg-subtle);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--cascivo-focus-ring);
    }

    &[aria-disabled='true'] {
      color: var(--cascivo-color-text-muted);
      cursor: not-allowed;
    }
  }

  .actionLabel {
    font-size: var(--cascivo-text-sm);
    white-space: nowrap;
  }

  .actionIcon {
    display: inline-flex;
    inline-size: 1.25rem;
    block-size: 1.25rem;
    color: var(--cascivo-color-accent-text);
  }

  @media (prefers-reduced-motion: reduce) {
    .dial,
    .icon {
      transition: none;
    }
  }
}

import type { ComponentMeta } from '@cascivo/core'

export const meta: ComponentMeta = {
  name: 'Fab',
  description:
    'Floating action button anchored to a screen corner, with an optional speed-dial of secondary actions',
  category: 'inputs',
  clientJs: 'required',
  states: ['default', 'open', 'closed'],
  variants: [],
  sizes: [],
  props: [
    { name: 'children', type: 'React.ReactNode', required: true, description: 'The main icon' },
    {
      name: 'ariaLabel',
      nameVisibility: 'invisible',
      description:
        'Alias of `label` — the same invisible accessible name under the catalog spelling. Neither is deprecated.',
      type: 'string',
      required: false,
    },
    {
      name: 'label',
      nameVisibility: 'invisible',
      type: 'string',
      required: false,
      description:
        'Accessible name for the main button (it is icon-only). Not rendered — screen readers only. Exactly one of `label` / `ariaLabel` is required; the type enforces it.',
    },
    {
      name: 'onClick',
      description: 'Called when the element is clicked.',
      type: '() => void',
      required: false,
    },
    {
      name: 'actions',
      type: 'FabAction[]',
      required: false,
      description: 'Speed-dial actions; each has a label, icon, onSelect, and optional disabled',
    },
    {
      name: 'position',
      description:
        'Screen corner the button is pinned to: `bottom-end` or `bottom-start`. Safe-area insets are honoured either way.',
      type: "'bottom-end' | 'bottom-start'",
      required: false,
      default: 'bottom-end',
    },
    {
      name: 'open',
      description: 'Whether the component is open (controlled).',
      type: 'boolean',
      required: false,
    },
    {
      name: 'defaultOpen',
      description: 'Whether the component is open on first render (uncontrolled).',
      type: 'boolean',
      required: false,
    },
    {
      name: 'onOpenChange',
      description: 'Called with the next open state when it changes.',
      type: '(open: boolean) => void',
      required: false,
    },
    {
      name: 'className',
      description: 'Additional CSS class names merged onto the root element.',
      type: 'string',
      required: false,
    },
  ],
  tokens: [
    '--cascivo-color-accent-text',
    '--cascivo-color-accent',
    '--cascivo-color-accent-content',
    '--cascivo-color-accent-hover',
    '--cascivo-color-surface',
    '--cascivo-color-border',
    '--cascivo-radius-full',
    '--cascivo-shadow-overlay',
    '--cascivo-target-min-coarse',
    '--cascivo-motion-enter',
    '--cascivo-motion-exit',
    '--cascivo-z-dropdown',
  ],
  accessibility: {
    role: 'button',
    wcag: '2.2-AA',
    keyboard: ['Enter', 'Space', 'ArrowUp', 'ArrowDown', 'Home', 'End', 'Escape'],
  },
  examples: [
    {
      title: 'Single action',
      code: '<Fab label="Compose" onClick={compose}><PlusIcon /></Fab>',
    },
    {
      title: 'Speed dial',
      code: `<Fab
  label="Create"
  actions={[
    { label: 'New note', icon: <NoteIcon />, onSelect: newNote },
    { label: 'New folder', icon: <FolderIcon />, onSelect: newFolder },
  ]}
>
  <PlusIcon />
</Fab>`,
      description: 'The main button toggles a menu of secondary actions.',
    },
    {
      title: 'Start corner',
      code: '<Fab label="Help" position="bottom-start" onClick={openHelp}><HelpIcon /></Fab>',
    },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['inputs', 'fab', 'floating-action-button', 'mobile', 'speed-dial'],
  intent: {
    whenToUse: [
      'A single, high-emphasis primary action that floats above scrolling content (e.g. Compose, Add)',
      'A small cluster of related create actions revealed from one corner via a speed-dial',
      'Touch-first screens where the primary action should stay reachable at the thumb',
    ],
    whenNotToUse: [
      'Ordinary form or toolbar buttons — use Button or IconButton in the layout flow',
      'More than a handful of actions — use a Menu, Drawer, or full navigation',
      'Primary navigation between top-level destinations — use Dock',
    ],
    antiPatterns: [
      {
        bad: '<Fab label="Save"><SaveIcon /></Fab> next to a form submit button',
        good: '<Button type="submit">Save</Button>',
        why: 'A floating button competes with the in-flow submit and hides the action off the form',
      },
    ],
    related: [
      {
        name: 'IconButton',
        relationship: 'alternative',
        reason: 'Use IconButton for an in-flow icon control; Fab floats and is high-emphasis',
      },
      {
        name: 'Dock',
        relationship: 'alternative',
        reason: 'Use Dock for bottom navigation between destinations rather than a single action',
      },
    ],
    a11yRationale:
      'The main button is icon-only and requires a `label` that becomes its aria-label. With a speed-dial it exposes aria-haspopup="menu", aria-expanded, and aria-controls; the dial is a role="menu" of role="menuitem" buttons under vertical roving focus (Arrow keys, Home/End, wrapping). Opening moves focus to the first action and closing (Escape, outside press, or selection via DismissableLayer) returns focus to the button.',
    flexibility: [
      {
        area: 'actions',
        level: 'flexible',
        note: 'Omit for a single-action button, or provide a speed-dial of secondary actions',
      },
      {
        area: 'position',
        level: 'strict',
        note: 'Anchored to bottom-end or bottom-start; honours safe-area insets',
      },
      {
        area: 'open state',
        level: 'flexible',
        note: 'Speed-dial is controlled (open/onOpenChange) or uncontrolled (defaultOpen)',
      },
    ],
  },
}
